mapper.update:
UPDATE gw_approval_doc
   SET status_cd = 'CANCELED', updated_at = CURRENT_TIMESTAMP
 WHERE doc_id = #{docId}
   AND drafter_id = #{requesterId}
   AND status_cd IN ('DRAFT','IN_PROGRESS')
   AND NOT EXISTS (
        SELECT 1 FROM gw_approval_line
         WHERE doc_id = #{docId} AND status_cd = 'APPROVED'
   )

mapper.select:
SELECT d.*, f.form_cd, f.form_nm, u.name AS drafter_name, dept.dept_nm AS drafter_dept FROM gw_approval_doc d JOIN gw_approval_form f ON f.form_id = d.form_id JOIN gw_user u ON u.user_id = d.drafter_id LEFT JOIN gw_dept dept ON dept.dept_id = u.dept_id WHERE d.drafter_id = #{drafterId}
AND d.status_cd = #{status}
ORDER BY d.created_at DESC LIMIT 200

SELECT d.*, f.form_cd, f.form_nm, u.name AS drafter_name, dept.dept_nm AS drafter_dept FROM gw_approval_doc d JOIN gw_approval_form f ON f.form_id = d.form_id JOIN gw_user u ON u.user_id = d.drafter_id LEFT JOIN gw_dept dept ON dept.dept_id = u.dept_id WHERE EXISTS ( SELECT 1 FROM gw_approval_line l WHERE l.doc_id = d.doc_id AND l.status_cd IN ('APPROVED','REJECTED') AND (l.approver_id = #{approverId} OR l.delegated_to_user_id = #{approverId}) )
AND d.status_cd = #{status}
ORDER BY d.completed_at DESC NULLS LAST, d.updated_at DESC LIMIT 200
